import json


def replay(recording, calls, live=None):
    """recording: list of (name, args, result) in the recorded order.
    calls: list of (name, args) the changed harness makes, in its order.
    Return a list of (result, status), status "replayed", "live" or "diverged"."""
    out = []
    for k, (name, args) in enumerate(calls):
        if k < len(recording):
            out.append((recording[k][2], "replayed"))
        elif live is not None:
            out.append((live(name, args), "live"))
        else:
            out.append((None, "diverged"))
            break
    return out

