questions.solution:
def classify(hook_blocked, approved, observation):
    """hook_blocked: True if the pre-tool hook stopped the call.
    approved: None when no approval was needed, else the approver's True or False.
    observation: what the tool returned, or None if it never ran.
    Return "blocked", "denied", "refused" or "ok"."""
    if hook_blocked:
        return "blocked"
    if approved is False:
        return "denied"
    if observation.startswith("blocked:"):
        return "refused"
    return "ok"
